INSERT INTO Language_ko_KR (Tag, Text) VALUES
('TXT_KEY_SPECIALUNIT_AIRBASE', '공항주둔기');


INSERT INTO Language_ko_KR (Tag, Text)
VALUES 
-- EARLY MONOPLANE
('TXT_KEY_UNIT_EARLYMONOPLAN','단엽기 (함재기)'),
('TXT_KEY_UNIT_HELP_EARLYMONOPLAN','다가오는 적 비행 유닛을 요격하고 제공권 장악을 목적으로 설계된 비행 유닛입니다.  [COLOR_POSITIVE_TEXT]군사 보급 한도를 차지하지 않습니다.[ENDCOLOR]'),
('TXT_KEY_UNIT_EARLYMONOPLAN_STRATEGY','단엽기는 당신이 소유한 모든 도시에 주둔하거나 항공모함에 탑승할 수 있습니다. 도시에서 도시(또는 항공모함)로 이동할 수 있으며 범위 내에서 "임무"를 수행할 수 있습니다. 전투기를 사용하여 적 항공기와 지상 유닛을 공격하고, 적 위치를 정찰하고, 적의 공중 공격을 방어하세요. 자세한 내용은 항공기 규칙을 참조하십시오.'),
('TXT_KEY_EARLYMONOPLAN_TEXT','전쟁(1919-1938) 사이에 항공 분야에서 많은 발전이 있었습니다. 비행기 디자인은 시속 80마일의 복엽기에서 시속 200마일 이상으로 하늘을 날 수 있는 경주용 비행기로 바뀌면서 크게 개선되었습니다. 1920년대에는 비행기의 발전으로 더 먼 거리를 비행하고 더 무거운 짐을 실을 수 있게 되면서 훨씬 더 신뢰할 수 있게 되었습니다. 대부분의 디자인은 조종사 바로 앞에 두 개의 동기화 된 기관총을 유지했지만 결국 전투기 무장은 날개 내부, 프로펠러 아크 외부에 장착되기 시작했습니다. 제1차 세계 대전 중에 인기를 끌었던 로터리 엔진은 회전력으로 인해 더 많은 연료와 공기가 실린더로 전달되지 않아 마력이 제한되는 지점에 도달하면서 빠르게 사라졌습니다. 그들은 주로 고정형 방사형 엔진으로 대체되었지만 주요 발전으로 인라인 엔진이 생겨 몇 가지 뛰어난 엔진으로 입지를 굳혔습니다.[NEWLINE]제한된 국방 예산을 감안할 때 공군은 항공기 구매에 보수적인 경향이 있었고 복엽기는 조종사들에게 여전히 인기가 있었습니다. 민첩성 때문에 경쟁이 멈춘 후에도 오랫동안 서비스를 유지했습니다. 글로스터 글래디에이터, 피아트 CR.42, 폴리카르포프 I-15와 같은 디자인은 1930년대 후반에도 흔했으며, 많은 것이 1942년 후반까지 여전히 사용되었습니다.[NEWLINE]이 시기에 등장한 가장 획기적인 전투기 중 하나입니다. 바르샤바에 본사를 둔 항공기 제조업체 PZL을 위해 항공 엔지니어 Zygmunt Pulawski가 개발한 PZL P.11이었습니다. 1934년 첫 비행. 순금속 구조, 금속 덮개, 높이 장착된 갈매기 날개를 갖춘 이 유형은 잠시 동안 세계에서 가장 진보된 전투기로 널리 간주되는 특징을 가졌습니다.[NEWLINE]이 최초의 단엽기 전투기는 총 325대가 제작되어 상당한 수출 성공을 거두었습니다.'),
-- P-80 Shooting Star
('TXT_KEY_UNIT_EARLYJET','P-80 슈팅스타 (공항주둔기)'),
('TXT_KEY_UNIT_HELP_EARLYJET','다가오는 적 비행 유닛을 요격하고 제공권 장악을 목적으로 설계된 비행 유닛입니다. [COLOR_POSITIVE_TEXT]군사 보급 한도를 차지하지 않습니다.[ENDCOLOR][NEWLINE][NEWLINE][COLOR_POSITIVE_TEXT]세계 불가사의인 펜타곤과 함께 2개가 제공됩니다.[ENDCOLOR][COLOR_NEGATIVE_TEXT] 다른 방법으론 생산이 불가합니다. [ENDCOLOR] [COLOR_POSITIVE_TEXT]그리고 4가지 추가 프로모션이 있습니다:[ENDCOLOR][NEWLINE][COLOR_YELLOW][NEWLINE][ICON_BULLET] 제공권 II[NEWLINE][ICON_BULLET] 공중 수리[NEWLINE][ICON_BULLET] 범위[NEWLINE][ICON_BULLET] 슈팅스타[ENDCOLOR][NEWLINE]'),
('TXT_KEY_UNIT_EARLYJET_STRATEGY','펜타곤 세계 불가사의를 건설한 문명에 두 개의 P-80 슈팅 스타가 무료로 제공됩니다. 다른 방법으로는 얻을 수 없습니다. 경험치는 없지만 기본적으로 높은 승격률을 자랑하는 P-80 슈팅 스타는 소유한 모든 도시에 주둔하고, 항공모함에 탑승할 수 없습니다. 도시에서 도시로만 이동할 수 있으며 범위 내에서 "임무"를 수행할 수 있습니다. 전투기를 사용하여 적 항공기와 지상 유닛을 공격하고, 적 위치를 정찰하고, 적의 공중 공격을 방어하세요. 자세한 내용은 항공기 규칙을 참조하십시오.'),
('TXT_KEY_EARLYJET_TEXT','P-80 슈팅 스타는 미국 육군 공군(USAAF)이 운용한 최초의 제트 전투기였습니다. 1943년 록히드에서 설계 및 제작되어 설계 프로세스 시작 후 불과 143일 만에 인도된 생산 모델은 비행 중이었고 두 개의 사전 생산 모델은 제2차 세계 대전이 끝나기 직전 이탈리아에서 매우 제한적인 서비스를 받았습니다. 직선 날개로 설계된 이 유형은 F-80으로 미국 공군(USAF)과 함께 한국에서 광범위한 전투를 보았습니다.'),
-- JET FIGHTER (supersonic)
('TXT_KEY_UNIT_JET27','제트기 (함재기)'),
('TXT_KEY_UNIT_HELP_JET27','다가오는 적 비행 유닛을 요격하고 제공권 장악을 목적으로 설계된 비행 유닛입니다. [COLOR_POSITIVE_TEXT]군사 보급 한도를 차지하지 않습니다.[ENDCOLOR]'),
('TXT_KEY_UNIT_JET27_STRATEGY','제트기는 강력한 비행 유닛입니다. 당신이 소유한 도시나 항공모함을 기반으로 할 수 있습니다. 기지 사이를 이동할 수 있으며 범위 내에서 "임무"를 수행할 수 있습니다. 제트기를 사용하여 적 항공기와 지상 유닛을 공격하고, 적 위치를 정찰하고, 적의 공중 공격을 방어하십시오. 제트기는 특히 적 헬리콥터에 효과적입니다. 제트기는 턴 시작 시 시작 위치에서 6타일 이내의 모든 것을 볼 수 있는 "공중 정찰" 능력이 있습니다. 자세한 내용은 항공기 규칙을 참조하십시오.'),
('TXT_KEY_JET27_TEXT','제트기(함재기)는 냉전 말기 미 해군이 “하나의 기체로 함대 방공과 공대지 타격을 모두 소화하라”는 다목적 요구에서 출발했습니다. YF-17을 해군형으로 개량한 F/A-18은 A-7 공격기와 일부 F-14 역할을 대체하며, “F(제공)/A(공격)” 복합 임무를 함상에서 반복적으로 수행하도록 설계되었습니다. 이후 동체·엔진·항전 장비를 대폭 키운 슈퍼 호넷 파생형으로 진화해 항모 항공단의 주력으로 자리 잡았습니다.[NEWLINE][NEWLINE]역사적으로 함재 전투기의 가장 큰 장점은 “움직이는 공군 기지”인 항공모함에서 국가 힘을 투사하는 능력이지만, 그만큼 공학적·운용적 제약도 혹독했습니다. 착함은 어레스터 후크를 걸고 수백 m 이내로 정지해야 하며(어레스터 케이블 파손에 대비해 스로틀을 끝까지 유지하는 “볼드 캐럿” 절차가 표준), 이 과정에서 랜딩기어·기체 프레임에 누적 피로가 급격히 쌓입니다. 염분과 습기가 높은 해상 환경은 전자장비·배선·기골 부식 속도를 가속시키고, 이를 상쇄하기 위해 방청 코팅과 부식 방지 재질, 배수·환기 설계를 강화해야 합니다. 함정의 제한된 갑판·격납고 공간은 날개 접이 구조와 낮은 기체 높이를 요구하고, 무장·연료 탑재량과 유지보수 접근성 사이에서 끊임없는 절충이 발생합니다.[NEWLINE]운용 측면에서도 함대 방공, 스트라이크, 근접항공지원(CAS), 대함/대레이더(SEAD/DEAD) 임무를 “사이클” 단위로 연속 수행해야 하므로, 무장 재장전·연료 충전·결빙/부식 점검·배선 검수 등 중정비와 경정비가 촘촘히 맞물립니다. 함대가 전개 중이면 바람 방향과 속도, 갑판 정리(Clear Deck), 발함/착함 윈도우가 임무 시각을 좌우하고, “브링백 무게 제한(착함 시 잔여 연료·무장 무게 상한)”은 임무 계획에 직접적 제약을 겁니다. 항모에서 이착함 가능한 전투기는 지상기와 달리 **CATOBAR**(사출/어레스팅) 혹은 **STOBAR**(스키점프/어레스팅) 체계에 맞춘 추력·기체 강성·랜딩기어 내구도를 갖춰야 하며, 이는 곧 최대 이륙중량과 항속·무장 선택지를 좁힙니다. 그럼에도 불구하고 함재 다목적 전투기는 항모 항공단의 “유연한 칼”로서, 제공권 장악과 해상/연안 타격을 하나의 비행대에서 통합 수행하며, 원해 억제와 신속 대응에서 독보적 실효성을 보여 왔습니다.'),
-- MiG-29
('TXT_KEY_UNIT_MIG29','MiG-29K (다목적기)'),
('TXT_KEY_UNIT_HELP_MIG29','다가오는 적 비행 유닛을 요격하고 제공권 장악을 목적으로 설계된 비행 유닛입니다. [COLOR_POSITIVE_TEXT]군사 보급 한도를 차지하지 않습니다.[ENDCOLOR][NEWLINE][NEWLINE]제로센과 마찬가지로, 적 전투기 대항시 전투력보너스가 증가하며 석유를 요구하지 않습니다. [NEWLINE][NEWLINE][ICON_IDEOLOGY_AUTOCRACY][COLOR_MAGENTA]독재[ENDCOLOR] 이념을 따르는 문명만 생산할 수 있고 [COLOR_MAGENTA]제공권[ENDCOLOR] 이념주의를 채택해야 합니다.'),
('TXT_KEY_UNIT_MIG29_STRATEGY','MiG-29는 독재 이념만 생산이 가능합니다. 제공권이념이 잠금 해제되어야 합니다. MiG-29는 결코 구식이 되지 않을 상당히 강력한 비행 유닛입니다. 다른 전투기와 싸울 때 상당한 전투 보너스를 받고 [COLOR_POSITIVE_TEXT]석유 자원[ENDCOLOR]이 필요하지 않다는 점을 제외하면 표준 제트기와 같습니다. 당신이 소유한 도시나 항공모함을 기반으로 할 수 있습니다. 도시에서 도시(또는 항공모함)로 이동할 수 있으며 9타일 범위 내에서 "임무"를 수행할 수 있습니다. 자세한 내용은 항공기 규칙을 참조하십시오.'),
('TXT_KEY_MIG29_TEXT','MiG-29K는 소련의 제공권 전투기 MiG-29를 바탕으로 한 함재 파생형이다. 1980년대 후반, 소련 해군 항공대가 신형 항모(킵급/쿠즈네초프급) 전력을 모색하면서 개발되었으나, 소련 붕괴로 대량 배치는 무산되었다. 이후 2000년대 들어 인도 해군의 항모 전력 재구축과 함께 프로그램이 부활하여, INS 비크라마디티야·비크란트 등에서 운용되며 러시아 해군도 제한적으로 채택했다. MiG-29K는 RD-33MK 엔진, 해상 환경 대응 항전장비, 대함·공대지 무장 통합, 접이식 날개와 강화된 착함장치, 부식 방지 처리 등 함상 운용을 위한 전면 개량이 이뤄진 다목적 함재 전투기다.[NEWLINE][NEWLINE]함재 운용은 설계·정비·전술 모든 면에서 난도가 높다. **STOBAR**(스키점프 이함·어레스팅 착함) 체계에선 사출기가 없으므로, 추력대중량비와 이함 속도를 맞추기 위해 연료·무장 탑재량에 제약이 걸리고, 이는 항속·무장 옵션에 직결된다. 착함은 짧은 갑판에서의 고하중 충격을 견딜 수 있도록 랜딩기어와 프레임이 크게 보강되며, 그 대가로 공허중량 증가와 유지보수 부담이 따라온다. 해상 염분 환경은 전자장비·배선·유압계통의 부식과 오작동 위험을 높이며, 격납고·갑판 공간 제약은 동시 정비 능력과 출격 회전율(소티 제너레이션)을 제한한다. 또한 항모 항공단의 “사이클 운용” 특성상 바람·갑판 상황에 맞춘 발함/착함 윈도우가 임무 계획의 제1 제약이 된다.[NEWLINE][NEWLINE]MiG-29K는 이런 한계를 보완하기 위해 대형 플랩/리드-엣지 장치, 개선된 비행제어법칙(FBW), 방위각·고각에서의 착함 안정성 향상, 해상 표적 탐지에 유리한 레이더 모드(예: 지상/해상 매핑·이동표적탐지)와 대함 미사일 운용 능력 등을 통합했다. 그럼에도 함상에서의 높은 피로 누적과 염분 부식, 예비품·정비 사이클의 촘촘한 관리가 전투가용률(Availability)을 좌우한다는 점은 변함없다. 결과적으로 MiG-29K는 항모 기반의 제공·대함·공대지 임무를 하나로 묶어 해군의 “원해 타격 팔”을 담당하지만, 그 성능은 함 자체의 발함 체계(STOBAR/CATOBAR), 함재 정비 인프라, 함대의 항법·조기경보·급유 네트워크와의 결합 수준에 의해 결정적으로 뒷받침된다.'),
-- ADVANCED FIGHTER (Stealth Jet)
('TXT_KEY_UNIT_ADVJET','다목적 스텔스제트기 (함재기)'),
('TXT_KEY_UNIT_HELP_ADVJET','다가오는 적 비행 유닛을 요격하고 제공권 장악을 목적으로 설계된 비행 유닛입니다. [COLOR_POSITIVE_TEXT]군사 보급 한도를 차지하지 않습니다.[ENDCOLOR][NEWLINE][NEWLINE][COLOR_POSITIVE_TEXT]항공모함에 함재가 가능합니다.[ENDCOLOR]'),
('TXT_KEY_UNIT_ADVJET_STRATEGY','다목적 스텔스제트기는 매우 강력한 비행 유닛입니다. 당신이 소유한 도시나 항공모함을 기반으로 할 수 있습니다. 기지 사이를 이동할 수 있으며 범위 내에서 "임무"를 수행할 수 있습니다. 어드밴스드 파이터를 사용하여 적 항공기와 지상 유닛을 공격하고, 적 위치를 정찰하고, 적의 공중 공격을 방어하십시오. 어드밴스드 파이터는 적 헬리콥터에 대해 특히 효과적이며 "공중 정찰" 능력이 있습니다. 즉, 턴 시작 시 시작 위치에서 6타일 내의 모든 것을 볼 수 있습니다. 자세한 내용은 항공기 규칙을 참조하십시오.'),
('TXT_KEY_ADVJET_TEXT','스텔스 전투기의 구상은 항공 초창기부터 이어졌지만, 냉전 말 등장한 F-22 랩터가 그 성능을 현실로 증명했습니다. 다만 랩터는 공군 제공전 전용으로 최적화되어 함재 운용 능력이 없었고, 높은 획득·유지 비용과 수출 제한까지 겹치며 소수만 배치되는 한계를 드러냈습니다. [NEWLINE][NEWLINE]냉전 종식 이후 미국은 F-16·F/A-18·AV-8B 등 노후 기종을 하나로 대체하고, 공군·해군·해병대가 공통으로 쓰며 비용을 낮출 “다목적 스텔스 전투기”를 필요로 했습니다. 특히 해병대는 단거리 이함/수직착륙(STOVL), 해군은 항모 운용(CATOBAR), 공군은 장거리 타격·센서 융합을 요구했습니다. 이 서로 다른 요구를 단일 플랫폼 계열로 풀기 위해 1990년대 “공동타격전투기(JSF)” 사업이 출범했고, 2001년 X-35가 채택되면서 F-35 라이트닝 II가 탄생했습니다. [NEWLINE][NEWLINE]F-35는 저피탐 형상과 내부 무장창을 바탕으로, AESA 레이더·EO/DAS·IRST·전자전 장비와 링크 기반 데이터 융합을 통합해 “먼저 보고–먼저 쏘고–먼저 이탈”을 구현합니다. 임무에 따라 내부 무장 중심의 저피탐 구성과 외부 하드포인트를 활용한 일명 “비스트 모드”를 오가며, 유지보수와 소티 생성률을 고려한 체계적 정비/소프트웨어 업그레이드 구조를 채택했습니다. [NEWLINE][NEWLINE]결과적으로 F-35는 F-22의 절대 제공 능력을 대체하기보다, 육·해·공 전력을 하나로 묶는 다목적 스텔스 플랫폼으로 설계되었습니다. 공군형(A), STOVL형(B), 함재형(C)의 세 파생형은 각 군의 운용 환경—공항, 강습함, 항공모함—에 맞춘 파생 능력을 제공하며, “랩터가 하늘을 열고(F-22), 라이트닝이 그 문을 통해 들어가 타격한다(F-35)”는 역할 분담을 완성했습니다'),
-- Light BOMBER
('TXT_KEY_UNIT_LIGHTBOMBER','경폭격기 (함재기)'),
('TXT_KEY_UNIT_HELP_LIGHTBOMBER','적 유닛과 도시를 폭격할 수 있는 비행 유닛입니다. [COLOR_POSITIVE_TEXT]군사 보급 한도를 차지하지 않습니다.[ENDCOLOR][NEWLINE][NEWLINE][COLOR_POSITIVE_TEXT]항공모함에 함재가 가능합니다.[ENDCOLOR]'),
('TXT_KEY_UNIT_LIGHTBOMBER_STRATEGY','경폭격기는 도시, 지상 목표물에 효과적이며 해상 목표물에는 덜 효과적이며 적 항공기에 매우 취약합니다. 경폭격기는 플레이어 소유의 도시를 기반으로 하거나 항공모함에 탑승할 수 있습니다. 기지 사이를 이동하며 범위 내에서 임무를 수행할 수 있습니다. 적 유닛과 도시를 공격하는 데 사용하십시오. 가능하면 단엽기나 전투기를 먼저 보내 해당 턴 동안 적의 대공 방어를 "사용"하십시오. 자세한 내용은 항공기 규칙을 참조하십시오.'),
('TXT_KEY_LIGHTBOMBER_TEXT','제1차 세계대전 종전(1918)부터 제2차 세계대전 발발(1939)까지의 사이 기간, 폭격기는 느린 목재 복엽기에서 빠르고 유선형의 금속 단엽기로 급격히 진화했습니다. 전금속 구조, 가변 피치 프로펠러, 공기역학 개선은 “속도로 생존하는” 경폭격기 개념을 낳았습니다. 영국의 브리스톨 블레넘(Bristol Blenheim)과 페어리 배틀(Fairey Battle), 미국의 더글러스 A-20 해복/보스턴(Douglas A-20 Havoc/Boston), 일본의 키-51 등은 비교적 가벼운 폭장과 높은 순항 속도를 앞세워 전장 전면에 신속히 타격을 가하도록 설계되었습니다.[NEWLINE][NEWLINE]그러나 전쟁이 본격화되자, 경폭격기는 빈약한 방어화기와 얇은 장갑, 제한된 폭장 때문에 치명적인 한계를 드러냈습니다. 특히 1940년 프랑스 전역에서 저고도 주간 침투에 투입된 페어리 배틀은 독일 전투기와 대공포 앞에 큰 손실을 입었고, 영국 공군은 빠르게 전술을 수정해 중·고고도 폭격기 운용과 호위 전투기 체계를 강화하게 됩니다. '),
-- STRATEGIC BOMBER
('TXT_KEY_UNIT_STRBOMB','전략폭격기 (공항주둔기)'),
('TXT_KEY_UNIT_HELP_STRBOMB','적 유닛과 도시를 강력하게 폭격할 수 있는 장거리 비행 유닛입니다. [COLOR_POSITIVE_TEXT]군사 보급 한도를 차지하지 않습니다.[ENDCOLOR]'),
('TXT_KEY_UNIT_STRBOMB_STRATEGY','전략 폭격기는 도시, 지상 목표물에 대해 효과적이며 해상 목표물에 대해서는 덜 효과적이며 적 항공기에 매우 취약합니다. 플레이어 소유의 도시를 기반으로 하고, 항공모함에 탑승할 수 없습니다. 기지 사이를 이동하며 범위 내에서 임무를 수행할 수 있습니다. 적 유닛과 도시를 공격하는 데 사용하십시오. 가능하면 파이터나 제트기를 먼저 보내 해당 턴 동안 적의 대공 방어를 "사용"하십시오. 자세한 내용은 항공기 규칙을 참조하십시오.'),
('TXT_KEY_STRBOMB_TEXT','전략 폭격기는 적의 전쟁 수행 능력을 약화시킬 목적으로 멀리 떨어진 목표물에 다량의 공대지 무기를 투하하도록 설계된 중장거리 관통 폭격기입니다. 전술 폭격기, 관통기, 전폭기, 공격기는 적의 전투원과 군사 장비를 공격하기 위해 공중 차단 작전에 사용되는 것과 달리 적의 영토로 날아가 전략적 목표(예: 인프라, 물류, 군사 설치, 공장 및 도시). 전략 폭격 외에도 전략 폭격기는 전술 임무에 사용될 수 있습니다.[NEWLINE]최초의 전략 폭격 노력은 제1차 세계 대전 중에 러시아인이 Sikorsky Ilya Muromets 폭격기(최초의 무거운 4개 엔진 항공기)를 사용하여 이루어졌습니다. Zeppelins 또는 장거리 다중 엔진 Gotha 항공기를 사용하는 독일군에 의해.[NEWLINE][NEWLINE]1930년대 후반에는 모든 전쟁에서 도시에 대한 전략적 "테러" 폭격이 빠르게 막대한 손실을 초래할 것이라고 널리 믿었습니다. 며칠 또는 몇 주 안에 충돌이 발생합니다. 그러나 이론상으로는 대부분의 공군이 실제로 공중에 투입할 수 있는 것보다 훨씬 뛰어났습니다.[NEWLINE]영국 왕립 공군은 1930년대 후반에야 4발 엔진 장거리 폭격기를 개발하기 시작했습니다. 미 육군 항공대(1941년 중반 현재 육군 공군)는 1930년대 후반에 적은 예산으로 인해 심각하게 제한을 받았고 곧 필수가 될 B-17 폭격기를 간신히 구했습니다. 똑같이 중요한 B-24는 1939년에 처음 비행했습니다. 두 항공기 모두 1943~45년에 연합군이 나치 독일에 대한 주간 폭격을 가능하게 만든 미국 폭격기 부대의 대부분을 구성했습니다.[NEWLINE][NEWLINE]냉전 기간 동안 미국은 한편으로는 미국과 영국, 다른 한편으로는 소련은 상호확증파괴(MAD) 억지 전략의 일환으로 갑작스럽게 이륙할 수 있는 전략 폭격기를 유지했습니다. 두 초강대국의 대부분의 전략 폭격기는 핵무기를 운반하도록 설계되었습니다. 한동안 Boeing B-52 Stratofortress 폭격기의 일부 편대는 소련 국경 근처의 안전 장치 지점에서 약간 떨어진 궤도를 돌면서 24시간 공중에 유지되었습니다.[NEWLINE][NEWLINE]항공기 유형의 크기 분류에 대한 명명법 전략 폭격에 사용되는 무기는 특히 제2차 세계 대전 이후 순차적인 기술 발전과 공중전 전략 및 전술의 변화로 인해 다양합니다. 예를 들어 B-29는 크기, 범위 및 적재 능력으로 인해 제2차 세계 대전 말 중 폭격기 유형의 벤치마크 항공기였습니다. 냉전이 시작되면서 공중급유(다른 중장거리 폭격기, 전폭기, 공격기의 사거리도 크게 확장됨)와 같은 새로운 기술의 개발로 대륙간 사정거리 전략 폭격기가 되었습니다. 1950년대에 미국 전략 공군 사령부(U.S. Strategic Air Command)는 또한 보잉 B-47 스트라토제트를 포격 날개에 있는 다소 큰 동시대의 보잉 B-52 스트라토포트리스 "중 폭격기"와 구별하기 위해 구식 용어인 "경폭격기"를 다시 사용했습니다. 구형 B-29 및 B-50 중 폭격기도 이 기간 동안 "경형"으로 재지정되었습니다. 폭격기 명명법은 순전히 의미론적이고 관료적이었지만, B-47과 B-52 전략 폭격기는 제2차 세계 대전 시대의 중폭격기 또는 중형 폭격기보다 훨씬 더 크고 성능과 적재 능력이 훨씬 뛰어났습니다. 쌍발 제트기 US FB-111, Douglas A-3 Skywarrior, 프랑스의 Dassault Mirage IV와 같은 다른 항공기는 공칭 무장량이 20,000lb(9,100kg) 미만이었고 전략 폭격기에 비해 크기와 총 중량이 훨씬 작았습니다. 중형 폭격기로 분류될 수 있습니다. 핵 공격 역할에서 프랑스는 1980년대 후반부터 Mirage IV를 훨씬 더 작은 단일 엔진 Mirage 2000N 전폭기로 교체했으며, 이는 군사 항공 및 항공기 설계에서 첨단 기술과 변화하는 전술의 또 다른 예입니다.'),
-- B-52
('TXT_KEY_UNIT_B52','B-52 (공항주둔기)'),
('TXT_KEY_UNIT_HELP_B52','적의 유닛과 도시 위로 죽음의 비를 내리는 장거리 비행 유닛입니다. 요격을 어느 정도 막아낼 수 있으며 전략폭격기보다 도시에 더 큰 피해와 범위가 증가합니다.[COLOR_POSITIVE_TEXT]군사 보급 한도를 차지하지 않습니다.[ENDCOLOR][NEWLINE][NEWLINE][ICON_IDEOLOGY_FREEDOM][COLOR_MAGENTA]평등[ENDCOLOR] 이념을 따르는 문명만 생산할 수 있고, [COLOR_MAGENTA]최고의 순간[ENDCOLOR] 이념 주의를 채택해야 합니다.'),
('TXT_KEY_UNIT_B52_STRATEGY','B-52 폭격기는 자유 이념에서만 생산 할 수 있습니다. 최상의 시간이 잠금 해제되어야 합니다. 폭격기와 비슷하지만 적의 대공 및 전투기가 조준하기가 더 어렵습니다. B-52는 또한 적 도시를 공격할 때 보너스를 받습니다. 잔략폭격기와 달리 범위는 14 (+1)입니다. 자세한 내용은 항공기 규칙을 참조하십시오.'),
('TXT_KEY_B52_TEXT','Stratofortress라고도 불리는 B-52는 1948년 보잉사에서 설계한 미국의 장거리 중폭격기로, 1952년에 처음 비행했으며 1955년에 군에 처음 인도되었습니다. 소련에 도착한 후 여러 임무에 적응할 수 있음이 입증되었으며 수십 대의 B-52가 21세기 초에 운용되었습니다. 날개 아래에 8개의 제트 엔진이 장착된 이 비행기의 최대 속도는 55,000피트에서 마하 0.9, 지상 수백 피트에서 마하 0.5입니다. B-52의 거대한 기체는 "Big Ugly Fat Fellow"(BUFF)라는 별명을 얻었지만 비행기에 고도로 정교한 항법, 무기 제어 및 전자 대응 시스템을 장착할 수 있게 했습니다. 수년 동안 폭격기는 X-15 및 X-43과 같은 공중 발사 실험용 항공기의 "모함" 역할을 자주 수행했습니다.'),
-- JET BOMBER
('TXT_KEY_UNIT_ULTJETBOMB','제트폭격기 (공항주둔기)'),
('TXT_KEY_UNIT_HELP_ULTJETBOMB','적의 유닛과 도시 위로 죽음의 비를 내리는 더 큰 타격을 주는 장거리 비행 유닛입니다.[NEWLINE][COLOR_POSITIVE_TEXT]군사 보급 한도를 차지하지 않습니다.[ENDCOLOR]'),
('TXT_KEY_UNIT_ULTJETBOMB_STRATEGY','제트 폭격기는 도시, 지상 목표물에 효과적이며 해상 목표물에는 덜 효과적이며 적 항공기에 매우 취약합니다. 플레이어 소유의 도시를 기반으로 하고, 항공모함에 탑승할 수 없습니다. 기지 사이를 이동하며 범위 내에서 임무를 수행할 수 있습니다. 적 유닛과 도시를 공격하는 데 사용하십시오. 가능하면 제트 전투기나 스텔스 전투기를 먼저 보내 해당 턴 동안 적의 대공 방어를 "사용"하십시오. 자세한 내용은 항공기 규칙을 참조하십시오.'),
('TXT_KEY_ULTJETBOMB_TEXT','냉전 종식 이후 장거리 폭격 개념은 저공 침투에서 원외(Stand-off) 타격중심으로 재편되었습니다. 광역 통합방공망(IADS)과 정밀유도무기의 확산으로, 제트폭격기는 스텔스·전자전 지원, 크루즈 미사일/활공탄/극초음속 무기 같은 “원거리 투발 수단”을 대량 운용하는 플랫폼으로 진화했습니다. 미 공군은 B-52를 재엔진/항전 현대화로 장수시켜 장거리 순항미사일 트럭으로 운용하고, B-1B는 재래식 타격에 특화되었습니다. 러시아는 Tu-160M, Tu-22M3M 개량을 통해 항속·전자장비를 갱신했습니다.[NEWLINE][NEWLINE]중국 역시 H-6K/H-6N 등 제트폭격기 계열을 대규모로 현대화해 장거리 공대지/대함 미사일을 탑재, [ICON_RANGE_STRENGTH] 사거리 밖에서 연안·해상 표적에 대한 접근거부/지역거부(A2/AD) 능력을 강화했습니다. 또한 차세대 스텔스 전략폭격기 개발이 공표되면서(세부 제원은 비공개), 향후에는 저피탐 설계와 장거리 무장, 네트워크 중심전이 결합된 “감지-결심-타격” 체계의 핵심 노드 역할이 예상됩니다.');

