UPDATE Language_ko_KR
SET Text = '양익 폭격기는 초기 비행 유닛입니다. 지상 목표물에 효과적이며 해상 목표물에는 덜 효과적이고, 적 항공기에 매우 취약합니다. 양익 폭격기는 그것은 당신이 소유한 도시에 주둔하고, 항공모함에는 탑승할 수 없습니다. 기지 간 재배치를 통해 이동하며 사거리 내에서 임무를 수행합니다. 적 유닛과 도시를 공격하는 데 사용하세요. 가능하다면, 같은 턴에 적의 대공 방어를 먼저 “소모”시키기 위해 삼엽기나 단엽기를 먼저 보내는 것이 좋습니다. 자세한 내용은 항공기 규칙을 참고하세요.'
WHERE Tag = 'TXT_KEY_UNIT_WWI_BOMBER_STRATEGY';

UPDATE Language_ko_KR
