SET Text = '스텔스무인전투기 편대 (다목적기)'
WHERE Tag = 'TXT_KEY_UNIT_FW_DRONE_FIGHTER_2'
  AND EXISTS (SELECT 1 FROM Units WHERE Type = 'UNIT_FW_DRONE_FIGHTER_2');

INSERT INTO Language_ko_KR (Tag, Text)
SELECT 'TXT_KEY_UNIT_FW_DRONE_FIGHTER_2', '스텔스무인전투기 편대 (함재기)'
WHERE EXISTS (SELECT 1 FROM Units WHERE Type = 'UNIT_FW_DRONE_FIGHTER_2')
  AND NOT EXISTS (SELECT 1 FROM Language_ko_KR WHERE Tag = 'TXT_KEY_UNIT_FW_DRONE_FIGHTER_2');


